// input
struct node
{
	int data;
	node* next;
};

// output
node* reverse(node* head)
{
    node* temp = head;
    node* prev = NULL;

    while(temp != NULL)
    {
        node* next = temp->next;
        temp->next = prev;
        prev = temp;
        temp = next;
    }

    return prev;
}
```

