// input
struct TreeNode
{
    int val;
    struct TreeNode *left;
    struct TreeNode *right;

    TreeNode(int x) {
        val = x;
        left = right = NULL;
    }
};

bool isBST(TreeNode *root)
{
    if (!root)
    {
        return true;
    }
    bool one = isBST(root->left);
    bool two = isBST(root->right);

    if (one && two)
    {
        return false;
    }
    return one && isBST(root->val) || (!one && isBST(root->val));
}

```

